//! Checking a tool call's arguments against the tool's declared JSON Schema
//! before it is dispatched (TODO §10).
//!
//! A model that sends `{"path": 3}` to a tool declaring `path` a string gets
//! told so, naming the path, rather than reaching the trait's `call` and
//! failing there in words the trait had to invent. The same failure counts as
//! a **malformed call** for the loop's cap.
//!
//! ## Why not the `jsonschema` crate
//!
//! Tool schemas here are small and written by hand or generated by
//! `sc-api`'s projection, and they use a small part of the draft: `type`,
//! `properties`, `required`, `additionalProperties`, `items`, `enum`, `const`,
//! the numeric and length bounds, `pattern`, `anyOf`/`oneOf`/`allOf` and the
//! OpenAPI `nullable`. That part is below. The crate would add a large
//! dependency tree (an HTTP client for remote `$ref`s among it) to every binary
//! that links the loop.
//!
//! **An unknown keyword is ignored, not refused.** A schema is the model's
//! instructions first; a keyword this checker does not know (`format`, `$ref`)
//! must not turn a well-formed call into a malformed one. The trait's own
//! `call` still validates what it reads.

use serde_json::Value as Json;

/// One way the arguments do not match the schema.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Violation {
    /// Where, as a JSON Pointer (`/edits/0/path`); empty for the arguments
    /// object itself.
    pub path: String,
    /// What is wrong, in words a model can act on.
    pub message: String,
}

impl std::fmt::Display for Violation {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        if self.path.is_empty() {
            write!(f, "the arguments: {}", self.message)
        } else {
            write!(f, "`{}`: {}", self.path, self.message)
        }
    }
}

/// Every violation of `schema` by `value`, in document order. Empty means the
/// value is valid.
///
/// A schema that is not an object (`true`, a missing schema) accepts anything,
/// and `false` accepts nothing.
pub fn validate(schema: &Json, value: &Json) -> Vec<Violation> {
    let mut out = Vec::new();
    check(schema, value, "", &mut out);
    out
}

/// The violations as one message, one per line, for a failed tool result.
pub fn describe(tool: &str, violations: &[Violation]) -> String {
    let mut text = format!("the arguments for `{tool}` do not match its schema:");
    for v in violations {
        text.push_str("\n- ");
        text.push_str(&v.to_string());
    }
    text
}

fn push(out: &mut Vec<Violation>, path: &str, message: impl Into<String>) {
    out.push(Violation {
        path: path.to_owned(),
        message: message.into(),
    });
}

fn check(schema: &Json, value: &Json, path: &str, out: &mut Vec<Violation>) {
    let schema = match schema {
        Json::Object(schema) => schema,
        Json::Bool(false) => {
            push(out, path, "no value is allowed here");
            return;
        }
        _ => return,
    };

    // OpenAPI's `nullable: true`, which `sc-api`'s projection emits: null is
    // valid whatever else the schema says.
    if value.is_null() && schema.get("nullable").and_then(Json::as_bool) == Some(true) {
        return;
    }

    if let Some(expected) = schema.get("type")
        && !type_matches(expected, value)
    {
        push(
            out,
            path,
            format!(
                "expected {}, got {}",
                type_names(expected),
                json_type(value)
            ),
        );
        // Every other keyword would only repeat the same mistake.
        return;
    }

    if let Some(Json::Array(options)) = schema.get("enum")
        && !options.iter().any(|o| o == value)
    {
        push(
            out,
            path,
            format!(
                "must be one of {}",
                options
                    .iter()
                    .map(Json::to_string)
                    .collect::<Vec<_>>()
                    .join(", ")
            ),
        );
    }
    if let Some(constant) = schema.get("const")
        && constant != value
    {
        push(out, path, format!("must be {constant}"));
    }

    match value {
        Json::Object(fields) => check_object(schema, fields, path, out),
        Json::Array(items) => check_array(schema, items, path, out),
        Json::String(s) => check_string(schema, s, path, out),
        Json::Number(n) => check_number(schema, n, path, out),
        Json::Bool(_) | Json::Null => {}
    }

    if let Some(Json::Array(all)) = schema.get("allOf") {
        for sub in all {
            check(sub, value, path, out);
        }
    }
    for keyword in ["anyOf", "oneOf"] {
        if let Some(Json::Array(options)) = schema.get(keyword) {
            let matching = options
                .iter()
                .filter(|sub| validate_at(sub, value, path).is_empty())
                .count();
            // `oneOf` is read as `anyOf`: a value matching two branches is not
            // what a model got wrong.
            if matching == 0 {
                let mut closest = options
                    .iter()
                    .map(|sub| validate_at(sub, value, path))
                    .min_by_key(Vec::len)
                    .unwrap_or_default();
                if closest.is_empty() {
                    push(out, path, "matches none of the allowed shapes");
                } else {
                    out.append(&mut closest);
                }
            }
        }
    }
}

fn validate_at(schema: &Json, value: &Json, path: &str) -> Vec<Violation> {
    let mut out = Vec::new();
    check(schema, value, path, &mut out);
    out
}

fn check_object(
    schema: &serde_json::Map<String, Json>,
    fields: &serde_json::Map<String, Json>,
    path: &str,
    out: &mut Vec<Violation>,
) {
    let properties = schema.get("properties").and_then(Json::as_object);
    if let Some(Json::Array(required)) = schema.get("required") {
        for name in required.iter().filter_map(Json::as_str) {
            if !fields.contains_key(name) {
                push(out, &pointer(path, name), "is required and was not given");
            }
        }
    }
    let additional = schema.get("additionalProperties");
    // Sorted, so the message does not depend on whether `serde_json` keeps
    // insertion order in this build.
    let mut names: Vec<&String> = fields.keys().collect();
    names.sort();
    for name in names {
        let field = &fields[name.as_str()];
        let at = pointer(path, name);
        match properties.and_then(|p| p.get(name)) {
            Some(sub) => check(sub, field, &at, out),
            None => match additional {
                Some(Json::Bool(false)) => {
                    let known = properties
                        .map(|p| {
                            p.keys()
                                .map(|k| format!("`{k}`"))
                                .collect::<Vec<_>>()
                                .join(", ")
                        })
                        .filter(|k| !k.is_empty())
                        .unwrap_or_else(|| "none".to_owned());
                    push(
                        out,
                        &at,
                        format!("is not a known argument; the arguments are {known}"),
                    );
                }
                Some(sub @ Json::Object(_)) => check(sub, field, &at, out),
                _ => {}
            },
        }
    }
}

fn check_array(
    schema: &serde_json::Map<String, Json>,
    items: &[Json],
    path: &str,
    out: &mut Vec<Violation>,
) {
    if let Some(min) = schema.get("minItems").and_then(Json::as_u64)
        && (items.len() as u64) < min
    {
        push(out, path, format!("must have at least {min} items"));
    }
    if let Some(max) = schema.get("maxItems").and_then(Json::as_u64)
        && (items.len() as u64) > max
    {
        push(out, path, format!("must have at most {max} items"));
    }
    if let Some(item_schema) = schema.get("items") {
        for (i, item) in items.iter().enumerate() {
            check(item_schema, item, &pointer(path, &i.to_string()), out);
        }
    }
}

fn check_string(
    schema: &serde_json::Map<String, Json>,
    s: &str,
    path: &str,
    out: &mut Vec<Violation>,
) {
    let len = s.chars().count() as u64;
    if let Some(min) = schema.get("minLength").and_then(Json::as_u64)
        && len < min
    {
        push(out, path, format!("must be at least {min} characters"));
    }
    if let Some(max) = schema.get("maxLength").and_then(Json::as_u64)
        && len > max
    {
        push(out, path, format!("must be at most {max} characters"));
    }
    if let Some(pattern) = schema.get("pattern").and_then(Json::as_str) {
        // A pattern this engine cannot compile is the schema author's problem,
        // not the model's, so it is not held against the call.
        if let Ok(re) = regex_lite::Regex::new(pattern)
            && !re.is_match(s)
        {
            push(out, path, format!("must match the pattern `{pattern}`"));
        }
    }
}

fn check_number(
    schema: &serde_json::Map<String, Json>,
    n: &serde_json::Number,
    path: &str,
    out: &mut Vec<Violation>,
) {
    let Some(x) = n.as_f64() else { return };
    if let Some(min) = schema.get("minimum").and_then(Json::as_f64)
        && x < min
    {
        push(out, path, format!("must be at least {min}"));
    }
    if let Some(max) = schema.get("maximum").and_then(Json::as_f64)
        && x > max
    {
        push(out, path, format!("must be at most {max}"));
    }
}

/// `path` with one more JSON Pointer segment, escaped.
fn pointer(path: &str, segment: &str) -> String {
    format!("{path}/{}", segment.replace('~', "~0").replace('/', "~1"))
}

fn type_matches(expected: &Json, value: &Json) -> bool {
    match expected {
        Json::String(name) => one_type_matches(name, value),
        Json::Array(names) => names
            .iter()
            .filter_map(Json::as_str)
            .any(|name| one_type_matches(name, value)),
        // A `type` of some other shape is not something to hold a call to.
        _ => true,
    }
}

fn one_type_matches(name: &str, value: &Json) -> bool {
    match name {
        "object" => value.is_object(),
        "array" => value.is_array(),
        "string" => value.is_string(),
        "boolean" => value.is_boolean(),
        "null" => value.is_null(),
        "number" => value.is_number(),
        // `3.0` is an integer to JSON Schema; `3.5` is not.
        "integer" => value
            .as_f64()
            .is_some_and(|x| x.fract() == 0.0 && x.is_finite()),
        _ => true,
    }
}

fn type_names(expected: &Json) -> String {
    match expected {
        Json::String(name) => article(name),
        Json::Array(names) => names
            .iter()
            .filter_map(Json::as_str)
            .map(article)
            .collect::<Vec<_>>()
            .join(" or "),
        other => other.to_string(),
    }
}

fn article(name: &str) -> String {
    match name {
        "object" | "array" | "integer" => format!("an {name}"),
        "null" => "null".to_owned(),
        other => format!("a {other}"),
    }
}

/// A value's JSON type, as a model reads it.
pub fn json_type(value: &Json) -> &'static str {
    match value {
        Json::Object(_) => "an object",
        Json::Array(_) => "an array",
        Json::String(_) => "a string",
        Json::Bool(_) => "a boolean",
        Json::Null => "null",
        Json::Number(n) if n.is_f64() => "a number",
        Json::Number(_) => "an integer",
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;

    fn edit_schema() -> Json {
        json!({
            "type": "object",
            "properties": {
                "path": {"type": "string", "minLength": 1},
                "line": {"type": "integer", "minimum": 1},
                "mode": {"type": "string", "enum": ["replace", "insert"]},
                "tags": {"type": "array", "items": {"type": "string"}},
                "note": {"type": "string", "nullable": true}
            },
            "required": ["path"],
            "additionalProperties": false
        })
    }

    #[test]
    fn a_valid_call_has_no_violations() {
        let args = json!({"path": "src/a.ts", "line": 3, "tags": ["x"], "note": null});
        assert_eq!(validate(&edit_schema(), &args), vec![]);
        // `3.0` is an integer.
        assert_eq!(
            validate(&edit_schema(), &json!({"path": "a", "line": 3.0})),
            vec![]
        );
    }

    #[test]
    fn a_missing_required_argument_is_named() {
        let v = validate(&edit_schema(), &json!({"line": 2}));
        assert_eq!(v.len(), 1);
        assert_eq!(v[0].path, "/path");
        assert!(v[0].message.contains("required"), "{:?}", v[0]);
    }

    #[test]
    fn a_wrong_type_is_named_with_both_types() {
        let v = validate(&edit_schema(), &json!({"path": 3, "line": 1.5}));
        assert_eq!(
            v.iter().map(ToString::to_string).collect::<Vec<_>>(),
            vec![
                "`/line`: expected an integer, got a number",
                "`/path`: expected a string, got an integer",
            ]
        );
        let v = validate(&edit_schema(), &json!("not an object"));
        assert_eq!(
            v[0].to_string(),
            "the arguments: expected an object, got a string"
        );
    }

    #[test]
    fn an_extra_property_is_named_with_the_known_ones() {
        let v = validate(&edit_schema(), &json!({"path": "a", "file": "b"}));
        assert_eq!(v.len(), 1);
        assert_eq!(v[0].path, "/file");
        assert!(v[0].message.contains("`path`"), "{}", v[0].message);
    }

    #[test]
    fn nested_items_bounds_and_enums_are_checked() {
        let v = validate(
            &edit_schema(),
            &json!({"path": "", "line": 0, "mode": "delete", "tags": ["a", 2]}),
        );
        let paths: Vec<&str> = v.iter().map(|v| v.path.as_str()).collect();
        assert_eq!(paths, vec!["/line", "/mode", "/path", "/tags/1"]);
    }

    #[test]
    fn any_of_reports_the_closest_branch_and_unknown_keywords_are_ignored() {
        let schema = json!({
            "anyOf": [
                {"type": "object", "properties": {"a": {"type": "string"}}, "required": ["a"]},
                {"type": "string", "format": "uuid"}
            ]
        });
        assert!(validate(&schema, &json!("anything")).is_empty());
        let v = validate(&schema, &json!({"a": 1}));
        assert_eq!(v[0].path, "/a");
        assert!(validate(&json!({"$ref": "#/x"}), &json!(1)).is_empty());
        assert!(!validate(&json!(false), &json!(1)).is_empty());
    }

    #[test]
    fn a_description_lists_every_violation() {
        let v = validate(&edit_schema(), &json!({"file": 1}));
        let text = describe("edit_file", &v);
        assert!(
            text.starts_with("the arguments for `edit_file` do not match"),
            "{text}"
        );
        assert_eq!(text.lines().count(), 3, "{text}");
    }
}
